#!/usr/bin/env node
// Source of truth: codex-pair-debounce-worker.mts. The sibling .mjs is generated by `yarn workspace @ask-llm/plugin build:hooks`; never edit it.
// The worker owns the per-file inflight lock for the whole forced review, then marks its generation done.
// Every path exits 0 (ADR-077).
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { decideReview, markReviewed, readEditRecord } from "./lib/debounce-state.mjs";
import { INFLIGHT_TTL_MIN_MS, releaseInflightLock, tryAcquireInflightLock } from "./lib/state.mjs";
const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const HOOK_PATH = join(SCRIPT_DIR, "codex-pair-watch.mjs");
const LOCK_CONTENTION_RETRY_MS = 100; // Pi's cadence
function sleep(ms) {
    return new Promise((r) => setTimeout(r, ms));
}
async function main() {
    const markerDir = process.env.CP_MARKER_DIR;
    const file = process.env.CP_FILE;
    const tool = process.env.CP_TOOL || "Edit";
    const myGeneration = Number(process.env.CP_GENERATION);
    const settleMs = Number(process.env.CP_SETTLE_MS);
    const rawMaxMs = Number(process.env.CP_MAX_MS);
    // NaN would disable the anti-starvation cap because comparisons always fail.
    const maxMs = Number.isFinite(rawMaxMs) && rawMaxMs > 0 ? rawMaxMs : 60_000;
    if (!markerDir || !file || !Number.isFinite(myGeneration))
        process.exit(0);
    await sleep(Number.isFinite(settleMs) ? settleMs : 15_000);
    const payload = JSON.stringify({
        hook_event_name: "PostToolUse",
        tool_name: tool,
        tool_input: { file_path: file },
        session_id: process.env.CP_SESSION_ID || "",
    });
    const codexTimeout = Number(process.env.ASK_CODEX_TIMEOUT_MS ?? 800_000);
    const lockTtlMs = Math.max(codexTimeout, INFLIGHT_TTL_MIN_MS) + 60_000;
    const giveUpAt = Date.now() + lockTtlMs;
    for (;;) {
        const decision = decideReview({ record: readEditRecord(markerDir, file), myGeneration, now: Date.now(), maxMs });
        if (!decision.review)
            break;
        const lock = tryAcquireInflightLock(markerDir, file, lockTtlMs);
        if (lock.acquired) {
            try {
                spawnSync(process.execPath, [HOOK_PATH], {
                    input: payload,
                    cwd: markerDir,
                    encoding: "utf-8",
                    env: { ...process.env, CODEX_PAIR_FORCE_SYNC: "1" },
                    timeout: codexTimeout + 60_000,
                });
            }
            finally {
                markReviewed(markerDir, file, myGeneration);
                releaseInflightLock(lock.lockPath);
            }
            break;
        }
        // Only the newest generation waits; an older cap-triggered worker leaves the settled review to it.
        if (lock.reason === "error" || decision.reason !== "settled" || Date.now() >= giveUpAt)
            break;
        await sleep(LOCK_CONTENTION_RETRY_MS);
    }
    process.exit(0);
}
main().catch(() => process.exit(0));
